//! `bsc sandbox` — inspect or REPLAY a caged session's exact launch (request #135), and REPAIR a
//! settings.json whose PreToolUse hooks name the sandbox-only guest path (request #188).
//!
//! A dev session hit a real gap: a caged pane's `bwrap`/`systemd-run` argv was never recorded
//! anywhere retrievable, so reproducing one outside the app meant grepping `journalctl` for a debug
//! line that does not exist and hand-extracting the command from it. `namespace_argv` (the launch
//! path in the desktop crate) now calls [`crate::write_launch_argv`] the moment a launch renders;
//! this is the READ side — the one verb the surface needed: `replay` prints the recorded argv, or
//! execs it directly so a session can drop straight into the same cage.
//!
//! `repair-hooks` closes a second, unrelated gap on the same guest path: a session's
//! `.claude/settings.json` can be WRITTEN while caged and then read again by a later, uncaged
//! launch of the same directory — `ensure_session_settings` in the desktop crate rewrites the file
//! on every launch, but a hub or worktree nothing has relaunched simply keeps whatever it last
//! wrote. `hook_floor_mismatch` (`session/settings.rs`) detects that state at launch and a pane's
//! own next launch now self-heals it ([`crate::rewrite_guest_hooks`]), but the fix has to reach the
//! files ALREADY sitting stale on disk too — this walks every project hub and worktree and does
//! that in one pass.

use crate::{read_launch_argv, sandbox_stores_root};
use bsc_cli_util::CmdDoc;

const TAGLINE: &str =
    "a caged session's rendered argv (replay) and its settings.json's sandbox-only hook path (repair)";

/// The crate's own verb catalog. `pub` so `bsc surface verbs` and the Glance crate drill can PROJECT
/// it rather than restate it — a generated catalog cannot drift, a second list does.
pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "replay",
        summary: "print or exec the exact bwrap/systemd-run argv a pane's caged launch used",
        usage: "\
USAGE:
  bsc sandbox replay <pane-id> [--exec]

Prints the exact argv the last caged launch of <pane-id> rendered to, one argument per line — the
argv IS the command, so there is no shell string to quote or misquote (see SandboxSpec::render).
Pipe it into an array to run it by hand:

  mapfile -t argv < <(bsc sandbox replay <pane-id>)
  \"${argv[@]}\"

--exec skips the mapfile step and execs it directly, replacing this process with the SAME cage the
pane launched — the actual point of `replay`. Unix-only (bwrap/systemd-run are Linux-only).

The record lives beside the pane's other per-session state and disappears with it: a pane that never
launched caged, or whose session already ended, has nothing to replay.",
    },
    CmdDoc {
        name: "repair-hooks",
        summary: "fix a settings.json whose PreToolUse hooks name the sandbox-only guest path (request #188)",
        usage: "\
USAGE:
  bsc sandbox repair-hooks [--dry-run]

A session's `.claude/settings.json` can end up naming the sandbox-only guest hook path — the
PreToolUse commands a NAMESPACED launch installs — while the session that reads it is NOT running
in a mount namespace. That happens when a directory was gated by a caged launch and a later,
uncaged launch of the SAME directory never followed (`hook_floor_mismatch`,
`session/settings.rs`, in the desktop crate). Every gate in that file then fails to execute,
NON-BLOCKING: the session runs with no write-scope gate and no dangerous-command floor.

This walks every project hub and worktree under $HOME/.base-studio-code (`projects/` and
`worktrees/`) for a `.claude/settings.json`, and rewrites each stale one in place — the two guest
commands map onto their host shell-function equivalents (`bsc-scope`, `bsc-deny`). --dry-run
reports which files WOULD change without writing anything.

A pane's OWN next launch already self-heals this on its own; this exists for hubs and worktrees
nothing has relaunched yet.",
    },
];

pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let positional: Vec<String> = args.iter().filter(|a| !a.starts_with("--")).cloned().collect();
    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &positional) {
        return Ok(());
    }
    match positional.first().map(String::as_str).unwrap_or_default() {
        "replay" => cmd_replay(&args, &positional, prog),
        "repair-hooks" => cmd_repair_hooks(&args),
        other => Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, other)),
    }
}

fn cmd_replay(args: &[String], positional: &[String], prog: &str) -> Result<(), String> {
    // The usage line is built from `prog`, not hard-coded: this surface is reached under three
    // spellings (`bsc session argv`, and the deprecated `bsc sandbox`), and a fixed string sent a
    // caller who typed the CURRENT one away to the deprecated noun.
    let pane_id = positional
        .get(1)
        .ok_or_else(|| format!("usage: {prog} replay <pane-id> [--exec]"))?;
    let exec = args.iter().any(|a| a == "--exec");
    let base = bsc_util::bsc_base_dir()
        .ok_or_else(|| "no HOME/USERPROFILE set — cannot locate the sandbox store".to_string())?;
    let root = sandbox_stores_root(&base, pane_id);
    let argv = read_launch_argv(&root).map_err(|e| {
        format!(
            "no recorded launch for pane {pane_id:?} at {} ({e}) — either it never launched caged, \
             or its session ended and the record went with it",
            root.display()
        )
    })?;
    if argv.is_empty() {
        return Err(format!("the recorded launch for pane {pane_id:?} is empty"));
    }
    if exec {
        #[cfg(unix)]
        {
            use std::os::unix::process::CommandExt;
            let err = std::process::Command::new(&argv[0]).args(&argv[1..]).exec();
            return Err(format!("exec {} failed: {err}", argv[0]));
        }
        #[cfg(not(unix))]
        {
            let _ = &argv;
            return Err("--exec needs unix — bwrap/systemd-run are Linux-only".to_string());
        }
    }
    for a in &argv {
        println!("{a}");
    }
    Ok(())
}

fn cmd_repair_hooks(args: &[String]) -> Result<(), String> {
    let dry_run = args.iter().any(|a| a == "--dry-run");
    let base = bsc_util::bsc_base_dir()
        .ok_or_else(|| "no HOME/USERPROFILE set — cannot locate project hubs".to_string())?;
    let fixed = repair_hooks_under(&base, dry_run)?;
    if fixed.is_empty() {
        println!("no stale guest-hook settings.json found under {}", base.display());
    } else {
        let verb = if dry_run { "would repair" } else { "repaired" };
        for path in &fixed {
            println!("{verb} {}", path.display());
        }
        println!("{} file(s) {}", fixed.len(), if dry_run { "would be repaired" } else { "repaired" });
    }
    Ok(())
}

/// How deep under `<base>/projects` or `<base>/worktrees` to look for a `.claude/settings.json` —
/// bounds the walk under a real repo checkout (which can otherwise be arbitrarily deep) without
/// missing any shape this store actually uses: a hub root, a hub's linked-repo subdir, or a
/// worktree dir (`<key>/<repo>--<slug>/`).
const SETTINGS_WALK_DEPTH: usize = 6;

/// Directory names never worth descending into looking for a session's OWN `.claude/settings.json`
/// — vendored/build trees that can be huge and never contain one relevant here.
const SKIP_DIR_NAMES: &[&str] = &[".git", "node_modules", "target", "dist", "build"];

/// Walk `<base>/projects` and `<base>/worktrees` for a stale `.claude/settings.json` (PreToolUse
/// hooks naming the sandbox-only guest path while nothing is running one) and rewrite each in place
/// unless `dry_run`. Returns the paths fixed — or, under `dry_run`, the paths that WOULD be fixed.
fn repair_hooks_under(base: &std::path::Path, dry_run: bool) -> Result<Vec<std::path::PathBuf>, String> {
    let mut candidates = Vec::new();
    for sub in ["projects", "worktrees"] {
        collect_settings_files(&base.join(sub), &mut candidates, SETTINGS_WALK_DEPTH);
    }
    candidates.sort();
    let mut fixed = Vec::new();
    for path in candidates {
        let Ok(raw) = std::fs::read_to_string(&path) else { continue };
        let Ok(mut config) = serde_json::from_str::<serde_json::Value>(&raw) else { continue };
        if !crate::rewrite_guest_hooks(&mut config) {
            continue;
        }
        if !dry_run {
            write_settings_atomic(&path, &config)
                .map_err(|e| format!("failed to repair {}: {e}", path.display()))?;
        }
        fixed.push(path);
    }
    Ok(fixed)
}

fn collect_settings_files(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>, depth: usize) {
    if depth == 0 {
        return;
    }
    let Ok(entries) = std::fs::read_dir(dir) else { return };
    for entry in entries.flatten() {
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if name == ".claude" {
            let settings = path.join("settings.json");
            if settings.is_file() {
                out.push(settings);
            }
            continue;
        }
        if SKIP_DIR_NAMES.contains(&name.as_ref()) {
            continue;
        }
        collect_settings_files(&path, out, depth - 1);
    }
}

fn write_settings_atomic(path: &std::path::Path, value: &serde_json::Value) -> std::io::Result<()> {
    let pretty = serde_json::to_string_pretty(value).map_err(std::io::Error::other)?;
    let tmp_name = format!("{}.tmp", path.file_name().unwrap_or_default().to_string_lossy());
    let tmp = path.with_file_name(tmp_name);
    std::fs::write(&tmp, pretty)?;
    std::fs::rename(&tmp, path)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn help_lists_replay_and_repair_hooks() {
        let help = bsc_cli_util::help_overview("bsc sandbox", TAGLINE, COMMANDS);
        assert!(help.contains("replay"));
        assert!(help.contains("repair-hooks"));
    }

    #[test]
    fn replay_with_no_pane_id_is_a_usage_error_not_a_panic() {
        let err = run(vec!["replay".into()], "bsc sandbox").unwrap_err();
        assert!(err.contains("usage"), "{err}");
    }

    #[test]
    fn replaying_an_unknown_pane_names_where_it_looked() {
        // A pane id unlikely to have ever launched caged on this machine.
        let err = run(
            vec!["replay".into(), "no-such-pane-ever-launched-abc123".into()],
            "bsc sandbox",
        )
        .unwrap_err();
        assert!(err.contains("no-such-pane-ever-launched-abc123"), "{err}");
        assert!(err.contains("sandbox-stores"), "{err}");
    }

    #[test]
    fn an_unknown_subcommand_is_reported_not_silently_ignored() {
        let err = run(vec!["bogus".into()], "bsc sandbox").unwrap_err();
        assert!(err.contains("bogus"));
    }

    #[test]
    fn repair_hooks_rewrites_a_stale_settings_json_under_a_project_hub() {
        let base = tempfile::tempdir().unwrap();
        let hub = base.path().join("projects").join("demo").join(".claude");
        std::fs::create_dir_all(&hub).unwrap();
        let settings = hub.join("settings.json");
        std::fs::write(
            &settings,
            r#"{"hooks":{"PreToolUse":[{"matcher":"Bash","hooks":[{"type":"command","command":"/bsc-hook bash-deny"}]}]}}"#,
        )
        .unwrap();

        let fixed = repair_hooks_under(base.path(), false).unwrap();

        assert_eq!(fixed, vec![settings.clone()]);
        let after = std::fs::read_to_string(&settings).unwrap();
        assert!(after.contains("bsc-deny"), "{after}");
        assert!(!after.contains("/bsc-hook"), "{after}");
    }

    #[test]
    fn repair_hooks_finds_a_stale_settings_json_under_a_worktree_too() {
        let base = tempfile::tempdir().unwrap();
        let wt = base.path().join("worktrees").join("demo").join("repo--slug").join(".claude");
        std::fs::create_dir_all(&wt).unwrap();
        let settings = wt.join("settings.json");
        std::fs::write(
            &settings,
            r#"{"hooks":{"PreToolUse":[{"matcher":"Edit","hooks":[{"type":"command","command":"/bsc-hook scope"}]}]}}"#,
        )
        .unwrap();

        let fixed = repair_hooks_under(base.path(), false).unwrap();

        assert_eq!(fixed, vec![settings.clone()]);
        assert!(std::fs::read_to_string(&settings).unwrap().contains("bsc-scope"));
    }

    #[test]
    fn dry_run_reports_without_writing() {
        let base = tempfile::tempdir().unwrap();
        let hub = base.path().join("projects").join("demo").join(".claude");
        std::fs::create_dir_all(&hub).unwrap();
        let settings = hub.join("settings.json");
        let original =
            r#"{"hooks":{"PreToolUse":[{"matcher":"Bash","hooks":[{"type":"command","command":"/bsc-hook bash-deny"}]}]}}"#;
        std::fs::write(&settings, original).unwrap();

        let fixed = repair_hooks_under(base.path(), true).unwrap();

        assert_eq!(fixed, vec![settings.clone()]);
        assert_eq!(std::fs::read_to_string(&settings).unwrap(), original, "dry-run must not write");
    }

    #[test]
    fn a_settings_json_already_on_host_hooks_is_left_alone() {
        let base = tempfile::tempdir().unwrap();
        let hub = base.path().join("projects").join("demo").join(".claude");
        std::fs::create_dir_all(&hub).unwrap();
        std::fs::write(
            hub.join("settings.json"),
            r#"{"hooks":{"PreToolUse":[{"matcher":"Bash","hooks":[{"type":"command","command":"bsc-deny"}]}]}}"#,
        )
        .unwrap();

        assert!(repair_hooks_under(base.path(), false).unwrap().is_empty());
    }

    #[test]
    fn never_descends_into_a_vendored_tree_looking_for_settings_json() {
        let base = tempfile::tempdir().unwrap();
        // A `.claude` directory nested under `node_modules` must never be reached — it isn't a
        // session's own settings, and a real checkout's node_modules can be enormous.
        let noise = base.path().join("projects").join("demo").join("node_modules").join(".claude");
        std::fs::create_dir_all(&noise).unwrap();
        std::fs::write(
            noise.join("settings.json"),
            r#"{"hooks":{"PreToolUse":[{"hooks":[{"type":"command","command":"/bsc-hook scope"}]}]}}"#,
        )
        .unwrap();

        assert!(repair_hooks_under(base.path(), false).unwrap().is_empty());
    }

    #[test]
    fn an_absent_projects_or_worktrees_dir_is_a_no_op_not_an_error() {
        let base = tempfile::tempdir().unwrap();
        assert_eq!(repair_hooks_under(base.path(), false).unwrap(), Vec::<std::path::PathBuf>::new());
    }

    /// THIS SURFACE IS REACHED UNDER MORE THAN ONE NOUN (`one-noun-answers-what-a-session-actually-gets`):
    /// `bsc session argv replay` is the spelling, and `bsc sandbox replay` the deprecated alias. A
    /// usage line that names one of them regardless of what was typed sends a caller who used the
    /// CURRENT noun away to the deprecated one — which is what it did before this was built from
    /// `prog`.
    #[test]
    fn the_replay_usage_line_names_the_noun_the_caller_actually_typed() {
        for prog in ["bsc session argv", "bsc sandbox"] {
            let err = cmd_replay(&[], &["replay".to_string()], prog).unwrap_err();
            assert!(err.contains(prog), "{prog}: {err}");
            assert!(err.contains("replay <pane-id>"), "{prog}: {err}");
        }
        // The one that must not happen: the current spelling pointing at the deprecated noun.
        let err = cmd_replay(&[], &["replay".to_string()], "bsc session argv").unwrap_err();
        assert!(!err.contains("bsc sandbox"), "{err}");
    }
}
